@isTest private class SquadBDomXmlEvidenceTest { @isTest static void domAndXmlRows() {
Dom.Document doc = new Dom.Document();
doc.load('<myprefix:node xmlns:myprefix="http://my.name.space" myprefix:type="test">hello<!--note--><child id="c">there</child></myprefix:node>');
Dom.XmlNode root = doc.getRootElement();
System.assertEquals(Dom.XmlNodeType.ELEMENT, root.getNodeType());
System.assertEquals('node', root.getName());
System.assertEquals('http://my.name.space', root.getNamespace());
System.assertEquals('myprefix', root.getPrefixFor('http://my.name.space'));
System.assertEquals('http://my.name.space', root.getNamespaceFor('myprefix'));
System.assertEquals(1, root.getAttributeCount());
System.assertEquals('type', root.getAttributeKeyAt(0));
System.assertEquals('http://my.name.space', root.getAttributeKeyNsAt(0));
System.assertEquals('test', root.getAttribute('type', 'http://my.name.space'));
System.assertEquals('test', root.getAttributeValue('type', 'http://my.name.space'));
System.assertEquals(null, root.getAttributeValueNs('type', 'http://my.name.space'));
System.assertEquals('hellonote', root.getText());
List<Dom.XmlNode> children = root.getChildren();
System.assertEquals(3, children.size());
System.assertEquals(1, root.getChildElements().size());
System.assertEquals('there', root.getChildElement('child', null).getText());
System.assertEquals(root, children[2].getParent());
Dom.XmlNode added = root.addChildElement('second', null, null);
added.addTextNode('added');
added.addCommentNode('comment');
added.setAttribute('plain', 'yes');
added.setAttributeNs('id', 's', null, null);
System.assertEquals('s', added.getAttributeValue('id', null));
System.assertEquals(true, added.removeAttribute('id', null));
added.setNamespace('p', 'urn:p');
System.assertEquals('urn:p', added.getNamespaceFor('p'));
System.assertEquals('p', added.getPrefixFor('urn:p'));
Dom.Document beforeDoc = new Dom.Document();
Dom.XmlNode before = beforeDoc.createRootElement('before', null, null);
before.addTextNode('first');
System.assertEquals(before, root.insertBefore(before, added));
System.assertEquals('before', root.getChildElements()[1].getName());
System.assert(doc.toXmlString().contains('<before>first</before><second'));
Dom.Document objectDoc = new Dom.Document();
Dom.XmlNode objectBefore = objectDoc.createRootElement('objectBefore', null, null);
objectBefore.addTextNode('object');
Object objectNewChild = objectBefore;
Object objectReferenceChild = added;
System.assertEquals(objectBefore, root.insertBefore(objectNewChild, objectReferenceChild));
System.assertEquals('objectBefore', root.getChildElements()[2].getName());
System.assertEquals(true, root.removeChild(added));
Object objectRemovedChild = objectBefore;
System.assertEquals(true, root.removeChild(objectRemovedChild));
Dom.Document built = new Dom.Document();
Dom.XmlNode request = built.createRootElement('request', null, null);
request.setAttribute('xmlns', 'urn:test');
request.addChildElement('name', null, null).addTextNode('local');
System.assertEquals('request', built.getRootElement().getName());
System.assert(built.toXmlString().contains('<name>local</name>'));
XmlStreamReader reader = new XmlStreamReader('<root xmlns:p="urn:p" p:id="7" name="Acme"><child> text </child></root>');
System.assertEquals(XmlTag.START_DOCUMENT, reader.getEventType());
System.assert(reader.hasNext());
reader.setCoalescing(true);
reader.setNamespaceAware(true);
System.assertEquals(1, reader.next());
System.assert(reader.isStartElement());
System.assert(reader.hasName());
System.assertEquals('root', reader.getLocalName());
System.assert(reader.toString().contains('XmlStreamReader')); 
System.assertEquals(2, reader.getAttributeCount());
System.assertEquals('id', reader.getAttributeLocalName(0));
System.assertNotEquals(null, reader.getAttributeNamespace(0));
System.assertNotEquals(null, reader.getAttributePrefix(0));
System.assertEquals('CDATA', reader.getAttributeType(0));
System.assertEquals('7', reader.getAttributeValueAt(0));
System.assertEquals('7', reader.getAttributeValue('urn:p', 'id'));
System.assertEquals(1, reader.getNamespaceCount());
System.assertEquals('p', reader.getNamespacePrefix(0));
System.assertEquals('urn:p', reader.getNamespaceURI('p'));
System.assertEquals('urn:p', reader.getNamespaceURIAt(0));
System.assertEquals('', reader.getLocation());
System.assertEquals('', reader.getNamespace());
System.assertEquals('', reader.getPrefix());
System.assertEquals('', reader.getPIData());
System.assertEquals('', reader.getPITarget());
System.assertEquals('1.0', reader.getVersion());
System.assertEquals(1, reader.nextTag());
System.assertEquals(4, reader.next());
System.assert(reader.isCharacters());
System.assert(reader.hasText());
System.assertEquals(false, reader.isWhiteSpace());
System.assertEquals(' text ', reader.getText());
System.assertEquals(2, reader.nextTag());
System.assert(reader.isEndElement());
} }
